-- A dead-lettered check delivery may be reopened (state back to pending) by an authorized requeue.
-- The frozen subject, payload, event and external id stay protected, and delivered rows stay terminal.
CREATE OR REPLACE FUNCTION protect_delivery() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF TG_OP='DELETE' THEN RAISE EXCEPTION 'immutable' USING ERRCODE='23514'; END IF; IF NEW.destination_ref<>OLD.destination_ref OR NEW.subject_sha<>OLD.subject_sha OR NEW.report_hash<>OLD.report_hash OR NEW.check_name<>OLD.check_name OR NEW.payload_hash<>OLD.payload_hash OR NEW.event_id<>OLD.event_id OR (OLD.external_id IS NOT NULL AND NEW.external_id IS DISTINCT FROM OLD.external_id) OR OLD.state='delivered' OR (OLD.state='dead_letter' AND NEW.state<>'pending') THEN RAISE EXCEPTION 'delivery_subject_frozen' USING ERRCODE='23514'; END IF; RETURN NEW; END $$;
